    """Fill gaps between consecutive sparse marker cells along rows and columns."""
    if not grid:
        return []
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [v for v in counts if v != background]
    if not markers:
        return [row[:] for row in grid]
    marker = max(markers, key=counts.get)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
